calls.params:
{
    state,
    ref: store.context.backdropRef,
    stateAttributesMapping: popupTransitionStateMapping,
    props: [
      { role: 'presentation', hidden: !store.select('mounted'), style: { userSelect: 'none', WebkitUserSelect: 'none' } },
      elementProps,
    ],
    enabled: forceRender || !store.select('nested'),
  }

{
    enabled: portal.keepMounted || store.select('mounted'),
    state,
    ref: setViewportElement,
    stateAttributesMapping: dialogStateAttributesMapping,
    props: [
      { role: 'presentation', hidden: !store.select('mounted'), style: { pointerEvents: !state.open ? 'none' : undefined } },
      elementProps,
    ],
  }

{
  state,
  ref: [buttonRef, forwardedRef, forwarding.registerTrigger, triggerElementRef],
  props: [
    click.reference, hoverProps(), rootTriggerProps, interactionTypeProps,
    { [CLICK_TRIGGER_IDENTIFIER]: '', id: thisTriggerId, 'aria-haspopup': 'dialog', 'aria-expanded': isOpenedByThisTrigger, 'aria-controls': store.select('triggerPopupId', thisTriggerId) },
    elementProps, getButtonProps,
  ],
  stateAttributesMapping: stateAttributesMapping,
}

{
  state,
  ref: [forwardedRef, forwarding.registerTrigger, triggerElementRef],
  props: [
    hoverProps(), focusProps.reference, rootTriggerProps, inlineRectTriggerProps, { id: thisTriggerId }, elementProps,
  ],
  stateAttributesMapping: triggerOpenStateMapping,
}

{
  state,
  ref: [forwardedRef, forwarding.registerTrigger, triggerElementRef],
  props: [
    hoverProps(), focus.reference, shouldApplyRootTriggerProps ? rootTriggerProps : undefined,
    {
      onmouseover(event: MouseEvent) { handleNestedTriggerHover(event); },
      onfocusin(event: FocusEvent & { preventBaseUIHandler(): void }) {
        if (isEnabledNestedTriggerTarget(getTargetElement(event))) event.preventBaseUIHandler();
      },
      onmouseleave() { isNestedTriggerHoveredRef.current = false; nestedTriggerOpenTimeout.clear(); pointerTypeRef.current = undefined; },
      onpointerenter(event: PointerEvent) { pointerTypeRef.current = event.pointerType; },
      onpointerdown(event: PointerEvent) {
        pointerTypeRef.current = event.pointerType;
        store.set('closeOnClick', closeOnClick);
        if (closeOnClick && !store.select('open')) store.cancelPendingOpen(event);
      },
      onclick(event: MouseEvent) { if (closeOnClick && !store.select('open')) store.cancelPendingOpen(event); },
      id: thisTriggerId,
      'data-trigger-disabled': disabled ? '' : undefined,
      [TOOLTIP_TRIGGER_IDENTIFIER]: disabled ? undefined : '',
    },
    elementProps,
  ],
  stateAttributesMapping: triggerOpenStateMapping,
}
